// Sort items by timestamp
items.sort((a, b) => new Date(a.json.Timestamp || a.json.timestamp) - new Date(b.json.Timestamp || b.json.timestamp));

const results = [];
let previousClosingBalance = null;
let dailyGroups = {};

// Identify and extract previous day summary
const firstItem = items[0].json;
const isSummary = firstItem.closingBalance !== undefined && !firstItem.TransactionID;

if (isSummary) {
  previousClosingBalance = parseFloat(firstItem.closingBalance);
  items.shift(); // Remove summary from list
}

// Group remaining transactions by date
for (const itemWrapper of items) {
  const item = itemWrapper.json;

  // Safe parsing
  item.Amount = parseFloat(item.Amount) || 0;
  item.TransactionCost = parseFloat(item.TransactionCost) || 0;
  item.Balance = parseFloat(item.Balance) || 0;

  const dateKey = item.Timestamp.split("T")[0];

  if (!dailyGroups[dateKey]) {
    dailyGroups[dateKey] = {
      transactions: [],
      firstTimestamp: item.Timestamp,
      date: item.Date,
    };
  }

  dailyGroups[dateKey].transactions.push(item);
}

// Now process each date group
for (const [dateKey, group] of Object.entries(dailyGroups)) {
  const transactions = group.transactions;
  const firstTx = transactions[0];
  const lastTx = transactions[transactions.length - 1];

  const totalTransactions = transactions.length;

  // Opening balance: use previous day's closing balance for first day, or derive from first transaction
  let openingBalance;
  if (previousClosingBalance !== null) {
    openingBalance = previousClosingBalance;
  } else {
    const firstAmount = firstTx.Amount;
    const isDebit = !firstTx.Sender || firstTx.Sender === "NIL";
    openingBalance = isDebit ? firstTx.Balance + firstAmount : firstTx.Balance - firstAmount;
  }

  // Calculate money spent/received
  let moneySpent = 0;
  let moneyReceived = 0;
  let transactionCost = 0;

  for (let i = 0; i < transactions.length; i++) {
    const current = transactions[i];
    const prevBal = i === 0 ? openingBalance : transactions[i - 1].Balance;
    const cost = current.TransactionCost || 0;
    transactionCost += cost;

    const delta = prevBal - current.Balance - cost;
    const rounded = Math.round(delta * 100) / 100;

    if (rounded > 0) {
      moneySpent += rounded;
    } else if (rounded < 0) {
      moneyReceived += -rounded;
    }
  }

  const closingBalance = lastTx.Balance;
  previousClosingBalance = closingBalance; // Set for next day

  // Generate ID
  const id = new Date(group.firstTimestamp).toISOString().replace(/:/g, '-');

  results.push({
    json: {
      id: id,
      date: group.date,
      timestamp: group.firstTimestamp,
      openingBalance: Math.round(openingBalance * 100) / 100,
      moneyReceived: Math.round(moneyReceived * 100) / 100,
      moneySpent: Math.round(moneySpent * 100) / 100,
      totalTransactions,
      transactionCost: Math.round(transactionCost * 100) / 100,
      closingBalance: Math.round(closingBalance * 100) / 100,
    }
  });
}

return results;

