// Safely extract timestamp
const rawTimestamp = items?.[0]?.json?.timestamp;
if (!rawTimestamp) {
  throw new Error("Missing timestamp in first item.");
}

const currentDate = new Date(rawTimestamp);
if (isNaN(currentDate.getTime())) {
  throw new Error("Invalid timestamp format.");
}

// Utility to format date as DD/MM/YY with leading zeroes
function formatDate(dateObj) {
  const day = String(dateObj.getDate());
  const month = String(dateObj.getMonth() + 1);
  const year = String(dateObj.getFullYear()).slice(-2);
  return `${day}/${month}/${year}`;
}

// Compute today, yesterday, and the day before yesterday
const leo = formatDate(currentDate);

const yesterdayDate = new Date(currentDate);
yesterdayDate.setDate(currentDate.getDate() - 1);
const jana = formatDate(yesterdayDate);

const juziDate = new Date(currentDate);
juziDate.setDate(currentDate.getDate() - 2);
const juzi = formatDate(juziDate);

return [{
  json: {
    leo,
    jana,
    juzi
  }
}];

const raw = $input.first().json.message;

// Remove leading/trailing whitespace and split lines
const lines = raw.trim().split('\n').map(l => l.trim()).filter(l => l);

// A regex to extract summary values
const re = {
  date: /📅 \*Daily M[-–—]?Pesa Summary\*.*?(\d{1,2}\/\d{1,2}\/\d{2,4})/,
  opening: /^💰 \*Opening Balance:\* Ksh(.+)$/,
  received: /^📥 \*Money Received:\* Ksh(.+)$/,
  spent: /^📤 \*Money Spent:\* Ksh(.+)$/,
  txCount: /^🧾 \*Total Transactions:\* (.+)$/,
  txCost: /^💸 \*Transaction Cost:\* Ksh(.+)$/,
  closing: /^🏁 \*Closing Balance:\* Ksh(.+)$/
};

const result = {};
for (const line of lines) {
  for (const key in re) {
    const m = line.match(re[key]);
    if (m) result[key] = m[1];
  }
}

// Ensure all values exist, else fallback to empty string
const params = [
  result.date || '',
  result.opening || '',
  result.received || '',
  result.spent || '',
  result.txCount || '',
  result.txCost || '',
  result.closing || ''
];

return [{
  json: {
    to: '254113220354',
    templateName: 'daily_mpesa_summary',
    languageCode: 'en_US',
    parameters: params.map(text => ({ type: 'text', text }))
  }
}];
